#!/usr/bin/env python3
"""Regenerate the standalone viewer from public derived JSON only."""
from pathlib import Path
import json,html
HERE=Path(__file__).resolve().parent
G=json.loads((HERE/'native_edge_graph.json').read_text())
C=json.loads((HERE/'complete_connection_review.json').read_text())
config=json.loads((HERE/'topology_candidate_fields.json').read_text())
parts=[]
for r in C['paired_head_plan_intervals']:
 a,b=r['world_X_interval_mm'];y=239.1666666667;parts.append(f'<rect class="band" x="{a}" y="{y}" width="{b-a}" height="39.5"><title>{r["lower_head_handle"]} + 4ED17: finite paired plan band; Z unknown</title></rect>')
for r in G['source_curves']:
 points=' '.join(f'{x},{y}'for x,y in r['points']);role=r['class'];kind='main'if role.startswith('MAIN_RAIL')else'detail'if role=='UNCONSUMED_OPEN_TURNOUT_DETAIL_TRACE'else'branch'if role=='TURNOUT_NATIVE_RAIL_BAND_EDGE'else'other';parts.append(f'<polyline class="edge {kind}" data-handle="{r["handle"]}" points="{points}"><title>{r["handle"]} · record {r["native_record_id"]} · {role}</title></polyline>')
svg='\n'.join(parts);fields='\n'.join(f'<li>{html.escape(k)}</li>'for k in config['fields_requiring_explicit_evidence_or_engineering_choice'])
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>GTSD 轨道有限源边界审阅</title><style>body{margin:0;background:#eef2f5;color:#193044;font:15px system-ui,sans-serif}header{padding:22px 28px;background:#193044;color:white}h1{font-size:22px;margin:0 0 8px}main{display:grid;grid-template-columns:300px 1fr;gap:18px;padding:18px}aside,section{background:white;border-radius:10px;padding:18px}button,select{padding:9px;margin:4px 2px;border:1px solid #afbec8;border-radius:5px;background:#fff}button.active{background:#193044;color:white}svg{width:100%;height:560px;background:#fbfdff;border:1px solid #d8e0e5}.edge{fill:none;stroke-width:1.8;vector-effect:non-scaling-stroke}.edge.main{stroke:#4267ad}.edge.branch{stroke:#c34247}.edge.detail{stroke:#169d6b;stroke-width:2.6}.edge.other{stroke:#9a9ea3}.band{fill:#4267ad;opacity:.1;stroke:none}.note{padding:12px;background:#fff4d5;border-left:3px solid #d19b17;line-height:1.6}.small{font-size:12px;color:#5a6d7a;overflow-wrap:anywhere}li{margin:7px 0}footer{padding:18px 28px}@media(max-width:850px){main{grid-template-columns:1fr}svg{height:440px}}</style><header><h1>GTSD · 轨道有限源边界</h1>57 条实际源曲线，5 段双边明确轨头平面约束。不是实装、材料切削或物理模型。</header><main><aside><b>视区</b><p><button onclick="view('all')">完整轨区</button><button onclick="view('crossing')">左侧交会</button><button onclick="view('right')">右侧连接</button></p><b>研究模式</b><p><select id="mode" onchange="mode(this.value)"><option value="source_only">仅源线（默认）</option><option value="straight_research">直向关联源线</option><option value="branch_research">侧向关联源线</option></select></p><p>蓝色：主轨有限边<br>红色：岔轨有限边<br>绿色：6 条细节链<br>浅蓝：5 段已知双边约束</p><p class="note">切换模式只突出相关源边。全部57条仍保留，不会删轨、开槽或产生一个“消穿”的实体。</p><b>生成实体前尚需确定</b><ul class="small">FIELDS</ul></aside><section><svg id="plot" viewBox="-9520 -400 1270 260" aria-label="57条原生轨道源曲线"><g transform="scale(1,-1)">SVG</g></svg><p class="small">鼠标停留在线上可看 handle、record_id 和源分类。坐标为控制台世界 XY 毫米；此处 Z=0 是绘图平面，不能当板厚或轨高。</p><p class="note">4ED15 并非主轨全部内侧头边：4ECED/C/B/A 也是有限分段。x≈−8970 mm 交会处确有两条原生直头边，当前轨头重叠不能仅归咎缺边外推。4ED5C/5D 的尖端分别落在4ECED/4ECFE内部，但平面接点不能独自确认零件归属或工作状态。</p><p>4ECEA → 4ECE9 → 4ED2C 是开放链。全2,738个直接Model实体排查未发现4ED2C尾端0.1 mm内的其他曲线续接。108.424 mm与3101.333 mm的水平边间断也不是删料许可。</p><p>护轨/外岔轨的旧交叠位于下部约 Z=−65 至−55.295 mm；内侧岔轨/主轨则连轨头层也重叠。只合并轨底不能解决后一类问题。</p></section></main><footer class="small">独立源几何审阅。已验收支承profile保持冻结；没有新增轨道实体或求解器修改。原照片未复制到本页。</footer><script>function view(v){const b={all:'-9550 -1050 11050 1550',crossing:'-9520 -400 1270 260',right:'-5350 -440 4050 320'};document.getElementById('plot').setAttribute('viewBox',b[v]);}function mode(v){document.querySelectorAll('.edge').forEach(e=>{e.style.opacity=v==='source_only'?'1':v==='straight_research'?(e.classList.contains('main')||e.classList.contains('detail')?'1':'.35'):(e.classList.contains('branch')||e.classList.contains('detail')?'1':'.35');});}</script></html>'''.replace('SVG',svg).replace('FIELDS',fields)
(HERE/'rail_source_review.html').write_text(page)
print('VIEWER_READY',len(G['source_curves']),'native curves; five fixed plan intervals; zero automatic material patches')
